import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join, normalize, relative } from "node:path";
import { AUTOGENERATED_DIR, PACKAGE_JSON, REQUIRED_PACKAGE_SCRIPTS } from "./constants.js";
import { isPathDiscovered, readDiscoveryPaths } from "./discovery-paths.js";
import { checkDockerBuildCache } from "./docker-build-cache.js";
import { checkDockerFileSharing } from "./docker-file-sharing.js";
import { checkStarlarkLoadExports } from "./doctor-starlark.js";
import { formatCount } from "./formatting.js";
import { declaresCommand } from "./native-service.js";
